mapper.select:
SELECT s.user_id AS userId, COALESCE(NULLIF(u.nickname,''),CONCAT('用户',s.user_id)) AS nickname,
       s.elapsed_ms AS elapsedMs,s.steps,s.hint_count AS hintCount
FROM game_number_puzzle_score s LEFT JOIN user u ON u.id=s.user_id
WHERE s.difficulty=#{difficulty}
AND s.created_at >= #{startTime}
AND NOT EXISTS (
  SELECT 1 FROM game_number_puzzle_score b WHERE b.user_id=s.user_id AND b.difficulty=s.difficulty
  AND b.created_at >= #{startTime}
  AND (b.elapsed_ms<s.elapsed_ms OR (b.elapsed_ms=s.elapsed_ms AND b.steps<s.steps) OR (b.elapsed_ms=s.elapsed_ms AND b.steps=s.steps AND b.created_at<s.created_at))
)
ORDER BY s.elapsed_ms ASC,s.steps ASC,s.created_at ASC LIMIT #{offset},#{limit}
